    {
        // Opt out of breaking changes if existing Cosmos documents use the
        // legacy "Discriminator" property and "EntityType|Key" id format.
        optionsBuilder.UseCosmos(o =>
        {
            // Placeholder – supply your actual connection details via
            // the standard UseCosmos overload in production code.
        });
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1 – Discriminator property renamed from "Discriminator" to "$type".
        // Preserve the old property name so existing documents keep working.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2 – Id format changed from "EntityType|Key" to just the key.
        // Preserve the legacy format so existing documents are still reachable.
        modelBuilder.Entity<Blog>().HasPartitionKey(e => e.Id);
        modelBuilder.Entity<Blog>().Property(e => e.Id)
            .HasJsonPropertyName("id");
        modelBuilder.Entity<Blog>()
            .UsePropertyAccessMode(PropertyAccessMode.Property);

        // Breaking change 3 – HasIndex() now throws for Cosmos provider.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
